        bucket[s]=w
    elif outcome=='value':assert row['returned_lo']==row['returned_hi']
    else:assert outcome=='none'

# Base bounds are derived from record provenance and effective screen instant.
local_bounds={}; bounds={}
for r in launches:
    s=suites[plan[r]['suite']]
    lo=units(s['random_guess']) if s['scoring']=='raw' else 0
    hi=SCALE
    if r in retention:
        if retention[r]['reason']=='below_retention_floor':
            assert retention[r]['dropped_at']==runtime[r]['finished_at']
            hi=min(hi,floor_at(retention[r]['dropped_at'])-1)
            assert not outage(r)
        else:
            assert retention[r]['reason']=='shard_file_lost'
            assert launches[r]['worker']=='w01'
            assert runtime[r]['finished_at'][:10]=='2026-07-04'
            lo=max(lo,floor_at(runtime[r]['finished_at']))
            assert not outage(r)
    elif not outage(r):
        # Normal rows reached the unchanged screen. All rejections are logged.
        lo=max(lo,floor_at(runtime[r]['finished_at']))
    assert lo<=hi,(r,lo,hi)
    if r in known:
        assert lo<=known[r]<=hi,(r,known[r],lo,hi)
        lo=hi=known[r]
    local_bounds[r]=(lo,hi)
    bounds[r]=(lo,hi)
for row in recovery:
    if row['outcome'] in ('range','value'):
        r=row['run_id'];lo,hi=bounds[r]
        bounds[r]=(max(lo,units(row['returned_lo'])),min(hi,units(row['returned_hi'])))
        assert bounds[r][0]<=bounds[r][1]

by_day=collections.defaultdict(list); by_config=collections.defaultdict(list)
for r in sorted(launches):
    by_day[runtime[r]['finished_at'][:10]].append(r)
    by_config[tuple(plan[r][k] for k in KNOBS)].append(r)
sums={x['date']:units(x['sum_pass_rate']) for x in digest}
assert set(by_day)==set(sums)
