    day=row['date'];rs=by_day[day]
    assert len(rs)==int(row['n_runs'])
    assert sum(bounds[r][0] for r in rs)<=sums[day]<=sum(bounds[r][1] for r in rs),day

# A missing state's return type is not identified by the sample. 'None' remains
# a possible answer for the whole state, and gives the worst possible residual.
def residual(r):
    lo,hi=local_bounds[r]
    outcome=mapping.get(states[r],'none')
    if outcome=='value':return 0
    if outcome=='range':return min(hi-lo,bucket[plan[r]['suite']])
    assert outcome=='none'
    return hi-lo

def config(q):return tuple(q[k] for k in KNOBS)
def coeffs(q):
    f=by_config[config(q['from'])];t=by_config[config(q['to'])]
    assert f and t
    a=collections.defaultdict(Fraction)
    for r in f:a[r]-=Fraction(1,len(f))
    for r in t:a[r]+=Fraction(1,len(t))
    return a

def sharp(q):
    a=coeffs(q)
    answers=[]
    for maximize in (False,True):
        value=Fraction(0)
        for day,rs in by_day.items():
            value+=sum((a[r]*bounds[r][0] for r in rs),Fraction(0))
            left=sums[day]-sum(bounds[r][0] for r in rs)
            for r in sorted(rs,key=lambda r:a[r],reverse=maximize):
                amt=min(left,bounds[r][1]-bounds[r][0]);left-=amt;value+=a[r]*amt
            assert left==0
        answers.append(value/SCALE)
    return tuple(answers)

def day_width(a,day,S):
    rs=by_day[day]
    C=sum(bounds[r][1]-bounds[r][0] for r in rs)
    t=sums[day]-sum(bounds[r][0] for r in rs)
    R=min(t,C-t)
    capacities=collections.defaultdict(int)
    for r in rs:
        d=bounds[r][1]-bounds[r][0]
        if r in S:d=min(d,residual(r))
        capacities[a[r]]+=d
    pairs=sorted((coef,cap) for coef,cap in capacities.items() if cap)
    value=Fraction(0)
    i=0;j=len(pairs)-1
    while i<j and R:
        low,lc=pairs[i];high,hc=pairs[j]
        amt=min(lc,hc,R)
        value+=(high-low)*amt
        R-=amt;lc-=amt;hc-=amt
        pairs[i]=(low,lc);pairs[j]=(high,hc)
        if not lc:i+=1
        if not hc:j-=1
    return value/SCALE

def width(q,S=(),details=False):
    a=coeffs(q);S=frozenset(S)
    parts={day:day_width(a,day,S) for day in by_day}
    return parts if details else sum(parts.values(),Fraction(0))

def print_summary():
    print('STATES',dict(collections.Counter(states.values())))
    print('RECOVERY mappings',mapping,'suite widths',bucket)
    print('DAILY sums/bounds (integer 1/10000 units)')
    for day,rs in by_day.items():
        vs=[r for r in rs if bounds[r][0]!=bounds[r][1]]
        lo=sum(bounds[r][0] for r in rs);hi=sum(bounds[r][1] for r in rs)
        print(day,'n',len(rs),'unknown',len(vs),'T-L',sums[day]-lo,'U-T',hi-sums[day], 'width',hi-lo)
